'use client';

import { useId, useImperativeHandle, useRef, useState } from 'react';

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import {
  PRESS_LEAD_MS,
  pressedQuietOf,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import {
  BookmarkIcon,
  CheckIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
} from '@/registry/ndeko/lib/icons';
import { FOCUS_RING } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { depthOf, useDeck } from './_parts/deck';
import { holdFocusOutsideCards, isOnControl, sideStepOf } from './_parts/keys';
import { PEOPLE } from './_parts/people';
import { useCardDemo } from './_parts/use-card-demo';

export type Contact = {
  id: string;
  name: string;
  role: string;
  company: string;
};

/** The control a demonstration holds down before it acts. */
export type ContactStackPress = 'save' | 'next';

export type ContactStackHandle = {
  next: () => void;
  previous: () => void;
  toggleSaved: () => void;
};

const LAST_LAYER = 2;
const PEEK_PX = 10;
const SCALE_STEP = 0.05;
const DROP_PX = 44;
const DROP_TILT_DEG = 3;
const LEAVE_MS = 240;

const CARD = [
  'bg-card hairline-ring ring-border absolute inset-x-0 bottom-0 flex h-36 origin-top flex-col justify-between rounded-xl p-4',
  'shadow-[0_1px_2px_rgb(0_0_0/0.04)] ease-(--ease-out-strong)',
].join(' ');

const FRONT = 'cursor-pointer hover:ring-foreground/25';

const TRAVELLING = 'transition-[transform,opacity] duration-300';

const PLACED = 'transition-none';

type Placement = { transform: string; opacity: number; zIndex: number };

function transformOf(offsetY: number, scale: number, tilt: number) {
  return `translateY(${offsetY}px) scale(${scale}) rotate(${tilt}deg)`;
}

function opacityOf(isShown: boolean) {
  if (isShown) {
    return 1;
  }
  return 0;
}

/** The front card sits lowest and largest; each card behind it shows a strip above it, and the fourth is hidden. */
function placementOf(depth: number, isOut: boolean, count: number): Placement {
  if (isOut) {
    const dropped = transformOf(DROP_PX, 1, DROP_TILT_DEG);
    const aboveAll = count + 1;
    return { transform: dropped, opacity: 0, zIndex: aboveAll };
  }
  const layer = Math.min(depth, LAST_LAYER);
  const lift = layer * -PEEK_PX;
  const shrink = layer * SCALE_STEP;
  const scale = 1 - shrink;
  const isShown = depth <= LAST_LAYER;
  const stackOrder = count - depth;
  return {
    transform: transformOf(lift, scale, 0),
    opacity: opacityOf(isShown),
    zIndex: stackOrder,
  };
}

function travelOf(isPlaced: boolean) {
  if (isPlaced) {
    return PLACED;
  }
  return TRAVELLING;
}

function saveLabelOf(isSaved: boolean) {
  if (isSaved) {
    return 'Saved';
  }
  return 'Save';
}

type ContactCardProps = {
  contact: Contact;
  placement: Placement;
  isFront: boolean;
  /** The card takes its pose at once, to travel from there on the next change. */
  isPlaced: boolean;
  /** A press on the card itself turns the stack: false for a stack of one. */
  canTurn: boolean;
  isSaved: boolean;
  isSavePressed: boolean;
  onToggleSaved: () => void;
  onTurn: () => void;
};

function ContactCard({
  contact,
  placement,
  isFront,
  isPlaced,
  canTurn,
  isSaved,
  isSavePressed,
  onToggleSaved,
  onTurn,
}: ContactCardProps) {
  const saveLabel = saveLabelOf(isSaved);
  const answersPress = isFront && canTurn;

  function turnFromCard(event: React.MouseEvent<HTMLLIElement>) {
    if (isOnControl(event.target)) {
      return;
    }
    onTurn();
  }

  return (
    <li
      style={placement}
      inert={!isFront}
      aria-hidden={!isFront}
      onClick={turnFromCard}
      className={cn(CARD, travelOf(isPlaced), answersPress && FRONT)}
    >
      <div className='flex items-center gap-3'>
        <Avatar seed={contact.name} className='size-10' />
        <div className='min-w-0'>
          <p className='truncate text-sm font-medium'>{contact.name}</p>
          <p className='text-muted-foreground truncate text-xs'>
            {contact.role}
          </p>
        </div>
      </div>
      <div className='flex items-center justify-between gap-3'>
        <p className='flex min-w-0 items-center gap-1.5 text-xs'>
          <CompanyMark seed={contact.company} size='sm' />
          <span className='truncate'>{contact.company}</span>
        </p>
        <Button
          type='button'
          size='sm'
          variant='outline'
          aria-pressed={isSaved}
          onClick={onToggleSaved}
          className={cn('w-[4.75rem]', pressedQuietOf(isSavePressed))}
        >
          <Swap swapKey={saveLabel}>
            {isSaved && <CheckIcon className='size-3.5' />}
            {!isSaved && <BookmarkIcon className='size-3.5' />}
          </Swap>
          {saveLabel}
        </Button>
      </div>
    </li>
  );
}

export type ContactStackProps = {
  contacts: Contact[];
  savedIds: readonly string[];
  onSavedChange: (contactId: string, isSaved: boolean) => void;
  /** Turns the stack or saves from outside, for a demonstration or a shortcut of the page. */
  handleRef?: React.Ref<ContactStackHandle>;
  /** Shows Save or Next held down, for a demonstration that presses it. */
  pressed?: ContactStackPress | null;
  /** Keeps the live region quiet while a demonstration turns the stack by itself. */
  isSilent?: boolean;
  label?: string;
  className?: string;
};

export function ContactStack({
  contacts,
  savedIds,
  onSavedChange,
  handleRef,
  pressed = null,
  isSilent = false,
  label = 'Contacts',
  className,
}: ContactStackProps) {
  const hintId = useId();
  const count = contacts.length;
  const deck = useDeck(count, LEAVE_MS);
  const frontContact = contacts[deck.front];
  const position = deck.front + 1;
  const canTurn = count > 1;
  const isSaveDown = pressed === 'save';
  const isNextDown = pressed === 'next';

  function isSavedContact(contact: Contact) {
    return savedIds.includes(contact.id);
  }

  function toggleSaved(contact: Contact) {
    const isSaved = isSavedContact(contact);
    onSavedChange(contact.id, !isSaved);
  }

  function toggleFrontSaved() {
    if (frontContact) {
      toggleSaved(frontContact);
    }
  }

  function turnWithKeys(event: React.KeyboardEvent<HTMLDivElement>) {
    const step = sideStepOf(event.key);
    if (step === 0) {
      return;
    }
    event.preventDefault();
    holdFocusOutsideCards(event.currentTarget);
    if (step === 1) {
      deck.next();
      return;
    }
    deck.previous();
  }

  useImperativeHandle(handleRef, () => ({
    next: deck.next,
    previous: deck.previous,
    toggleSaved: toggleFrontSaved,
  }));

  if (!frontContact) {
    return (
      <p className='hairline-border border-foreground/20 text-muted-foreground flex h-36 w-full items-center justify-center rounded-xl border-dashed text-[13px]'>
        No contacts yet
      </p>
    );
  }

  const announcement = `${frontContact.name}, ${frontContact.role} at ${frontContact.company}, ${position} of ${count}`;

  return (
    <div
      role='group'
      aria-roledescription='carousel'
      aria-label={label}
      aria-describedby={hintId}
      tabIndex={0}
      onKeyDown={turnWithKeys}
      className={cn(
        'flex w-full flex-col gap-3 rounded-xl',
        FOCUS_RING,
        className
      )}
    >
      <ul className='relative h-[10.25rem]'>
        {contacts.map((contact, index) => {
          const depth = depthOf(index, deck.front, count);
          const isOut = index === deck.out;
          const isFront = depth === 0;
          const isPlaced = isOut && deck.isReturning;
          const isSavePressed = isFront && isSaveDown;
          return (
            <ContactCard
              key={contact.id}
              contact={contact}
              placement={placementOf(depth, isOut, count)}
              isFront={isFront}
              isPlaced={isPlaced}
              canTurn={canTurn}
              isSaved={isSavedContact(contact)}
              isSavePressed={isSavePressed}
              onToggleSaved={() => toggleSaved(contact)}
              onTurn={deck.next}
            />
          );
        })}
      </ul>
      <div className='flex h-7 items-center justify-between gap-2 ps-1'>
        <p className='text-muted-foreground text-xs tabular-nums'>
          {position} of {count}
        </p>
        {canTurn && (
          <div className='flex items-center gap-1'>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label='Previous contact'
              onClick={deck.previous}
              className='text-muted-foreground'
            >
              <ChevronLeftIcon />
            </Button>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label='Next contact'
              onClick={deck.next}
              className={cn(
                'text-muted-foreground',
                pressedQuietOf(isNextDown)
              )}
            >
              <ChevronRightIcon />
            </Button>
          </div>
        )}
      </div>
      <span id={hintId} className='sr-only'>
        Left and Right arrows turn the stack
      </span>
      <LiveRegion message={spokenUnless(isSilent, announcement)} />
    </div>
  );
}

const CONTACTS: Contact[] = [
  PEOPLE.amara,
  PEOPLE.jonas,
  PEOPLE.mei,
  PEOPLE.rafael,
  PEOPLE.ingrid,
];

function withSaved(savedIds: string[], contactId: string, isSaved: boolean) {
  const others = savedIds.filter((savedId) => savedId !== contactId);
  if (isSaved) {
    return [...others, contactId];
  }
  return others;
}

export default function Card01() {
  const [savedIds, setSavedIds] = useState<string[]>([]);
  const stack = useRef<ContactStackHandle>(null);
  const { pressed, press } = usePress<ContactStackPress>();

  function changeSaved(contactId: string, isSaved: boolean) {
    setSavedIds((current) => withSaved(current, contactId, isSaved));
  }

  const steps: AutoplayStep[] = [
    { after: 1500, run: () => press('save') },
    { after: PRESS_LEAD_MS, run: () => stack.current?.toggleSaved() },
    { after: 1200, run: () => press('next') },
    { after: PRESS_LEAD_MS, run: () => stack.current?.next() },
  ];
  const { ref, isAutoplaying } = useCardDemo(steps, {
    loopAfter: 700,
  });

  return (
    <div ref={ref} className='min-h-[12.75rem] w-full max-w-[21rem]'>
      <ContactStack
        contacts={CONTACTS}
        savedIds={savedIds}
        onSavedChange={changeSaved}
        handleRef={stack}
        pressed={pressed}
        isSilent={isAutoplaying}
      />
    </div>
  );
}

'use client';

import { useCallback, useLayoutEffect, useReducer } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';

type DeckDirection = 1 | -1;

type DeckState = {
  front: number;
  /** The card held out of the deck for a moment: the one that left the front, or the one about to come back to it. */
  out: number | null;
  /** The out card waits in its pose, then comes back to the front from there. */
  isReturning: boolean;
};

type DeckAction =
  | { type: 'leave'; count: number }
  | { type: 'summon'; count: number }
  | { type: 'jump'; direction: DeckDirection; count: number }
  | { type: 'land' };

const RESTING: DeckState = { front: 0, out: null, isReturning: false };

/** An index that runs past either end of a list comes back in at the other end. */
export function wrapIndex(index: number, count: number) {
  if (count <= 0) {
    return 0;
  }
  const remainder = index % count;
  const positive = remainder + count;
  return positive % count;
}

/** How many cards sit in front of this one: 0 for the front card. */
export function depthOf(index: number, front: number, count: number) {
  const behind = index - front;
  return wrapIndex(behind, count);
}

function landed(deck: DeckState): DeckState {
  if (deck.out === null) {
    return deck;
  }
  if (deck.isReturning) {
    return { front: deck.out, out: null, isReturning: false };
  }
  return { front: deck.front, out: null, isReturning: false };
}

function reduceDeck(deck: DeckState, action: DeckAction): DeckState {
  const settled = landed(deck);
  if (action.type === 'land') {
    return settled;
  }
  if (action.type === 'jump') {
    const stepped = settled.front + action.direction;
    const front = wrapIndex(stepped, action.count);
    return { front, out: null, isReturning: false };
  }
  if (action.type === 'leave') {
    const stepped = settled.front + 1;
    const front = wrapIndex(stepped, action.count);
    return { front, out: settled.front, isReturning: false };
  }
  const before = settled.front - 1;
  const out = wrapIndex(before, action.count);
  return { front: settled.front, out, isReturning: true };
}

/**
 * A deck that turns one card at a time. Going forward, the front card is held out while the others
 * step up, then it joins the back. Going back, the last card is placed out first and comes to the
 * front from there. Each piece draws the out pose its own way: dropped, swung aside.
 */
export function useDeck(count: number, leaveMs: number) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const [deck, dispatch] = useReducer(reduceDeck, RESTING);
  const { schedule, clearAll } = useTimeouts();
  const canTurn = count > 1;

  useLayoutEffect(() => {
    if (!deck.isReturning) {
      return;
    }
    // A transition starts from the last pose the browser applied. Reading a layout value applies
    // the out pose now, so the card travels from there and not from the back of the deck.
    document.body.getBoundingClientRect();
    const frame = requestAnimationFrame(() => dispatch({ type: 'land' }));
    return () => cancelAnimationFrame(frame);
  }, [deck.isReturning, deck.out]);

  const next = useCallback(() => {
    if (!canTurn) {
      return;
    }
    clearAll();
    if (shouldReduceMotion) {
      dispatch({ type: 'jump', direction: 1, count });
      return;
    }
    dispatch({ type: 'leave', count });
    schedule(() => dispatch({ type: 'land' }), leaveMs);
  }, [canTurn, clearAll, count, leaveMs, schedule, shouldReduceMotion]);

  const previous = useCallback(() => {
    if (!canTurn) {
      return;
    }
    clearAll();
    if (shouldReduceMotion) {
      dispatch({ type: 'jump', direction: -1, count });
      return;
    }
    dispatch({ type: 'summon', count });
  }, [canTurn, clearAll, count, shouldReduceMotion]);

  const front = wrapIndex(deck.front, count);

  return {
    front,
    out: deck.out,
    isReturning: deck.isReturning,
    next,
    previous,
  };
}

/** The step an arrow key asks for along a row: -1 for Left, 1 for Right, 0 for any other key. */
export function sideStepOf(key: string) {
  if (key === 'ArrowLeft') {
    return -1;
  }
  if (key === 'ArrowRight') {
    return 1;
  }
  return 0;
}

/** True when a press landed on a control inside a surface that also answers presses of its own. */
export function isOnControl(target: EventTarget) {
  if (!(target instanceof Element)) {
    return false;
  }
  return target.closest('button, a, input') !== null;
}

/** True when the keyboard brings focus into an element from outside it, not when focus moves within it. */
export function isKeyboardArrival(event: React.FocusEvent<HTMLElement>) {
  const isKeyboardFocus = event.target.matches(':focus-visible');
  const cameFromInside = event.currentTarget.contains(event.relatedTarget);
  return isKeyboardFocus && !cameFromInside;
}

/**
 * A card that goes behind the others turns inert and would drop the focus it holds. Before a deck
 * turns from the keyboard, the group takes the focus, so the next arrow key still reaches it.
 */
export function holdFocusOutsideCards(group: HTMLElement) {
  const focused = document.activeElement;
  if (!(focused instanceof Element)) {
    return;
  }
  const card = focused.closest('li');
  if (!card) {
    return;
  }
  if (group.contains(card)) {
    group.focus();
  }
}

export type Person = {
  id: string;
  name: string;
  role: string;
  company: string;
};

/** The invented people of the card demos. The same person keeps the same picture on every card. */
export const PEOPLE = {
  amara: {
    id: 'amara',
    name: 'Amara Diallo',
    role: 'Product lead',
    company: 'Halden Works',
  },
  jonas: {
    id: 'jonas',
    name: 'Jonas Weber',
    role: 'Staff engineer',
    company: 'Brightwater',
  },
  mei: {
    id: 'mei',
    name: 'Mei Tanaka',
    role: 'Design director',
    company: 'Kiln Studio',
  },
  rafael: {
    id: 'rafael',
    name: 'Rafael Ortega',
    role: 'Head of support',
    company: 'Tallyard',
  },
  ingrid: {
    id: 'ingrid',
    name: 'Ingrid Solheim',
    role: 'Finance manager',
    company: 'Quillhouse',
  },
} satisfies Record<string, Person>;

'use client';

import {
  useAutoplay,
  type AutoplayOptions,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';

/**
 * What every card demo shares: the demonstration, and the box that keeps its tallest height so a
 * round never moves the page.
 */
export function useCardDemo(
  steps: readonly AutoplayStep[],
  options?: AutoplayOptions
) {
  const demo = useAutoplay(steps, options);
  const { ref } = demo;

  useKeptHeight(ref);

  return demo;
}
